<template><div class="page"><div class="page-header"><div><h2>预算管理</h2><p>查看预算使用情况，管理员可新增和调整预算</p></div><button v-if="isAdmin" class="primary" @click="openAdd">＋ 新增预算项目</button></div><div class="table-box"><table><thead><tr><th><button @click="sort">预算编号 {{ idSort==='asc'?'↑':'↓' }}</button></th><th>年份</th><th>预算类别</th><th>预算金额</th><th>已使用</th><th>剩余</th><th>使用率</th><th>状态</th><th v-if="isAdmin">操作</th></tr></thead><tbody><tr v-for="item in sortedList" :key="item.id"><td>#{{item.id}}</td><td>{{item.year}}</td><td><span class="tag">{{item.category}}</span></td><td>￥{{money(item.budgetAmount)}}</td><td>￥{{money(item.usedAmount)}}</td><td>￥{{money(left(item))}}</td><td>{{rate(item)}}%</td><td><span class="status" :class="level(item)">{{text(item)}}</span></td><td v-if="isAdmin"><button class="adjust" @click="openAdjust(item)">调整预算</button></td></tr><tr v-if="!list.length"><td :colspan="isAdmin?9:8" class="empty">暂无预算数据</td></tr></tbody></table></div><div v-if="show" class="mask" @click.self="show=false"><div class="modal"><div class="head"><div><h3>{{mode==='add'?'新增预算项目':'调整预算'}}</h3><p>{{mode==='add'?'为报销类别配置年度预算':current.year+' 年 · '+current.category}}</p></div><button @click="show=false">×</button></div><template v-if="mode==='add'"><label>预算年度</label><input v-model.number="form.year" type="number"><label>预算类别</label><div class="select"><select v-model="form.category"><option value="" disabled>请选择费用类别</option><option v-for="x in categories" :key="x">{{x}}</option></select></div></template><template v-else><div class="info">当前预算 <strong>￥{{money(current.budgetAmount)}}</strong>&nbsp;已使用 ￥{{money(current.usedAmount)}}</div><div class="switch"><button :class="{active:increase}" @click="increase=true">追加预算</button><button :class="{active:!increase}" @click="increase=false">削减预算</button></div></template><label>{{mode==='add'?'初始预算金额':(increase?'追加金额':'削减金额')}}</label><div class="money"><span>￥</span><input v-model.number="form.amount" type="number" min="0.01" placeholder="请输入金额"></div><p v-if="mode==='adjust'&&!increase" class="hint">削减后不得低于已使用金额 ￥{{money(current.usedAmount)}}</p><div class="foot"><button class="cancel" @click="show=false">取消</button><button class="primary" @click="submit">确认{{mode==='add'?'新增':'调整'}}</button></div></div></div></div></template>
<script>
import {api,currentUser} from '../api'
export default {name:'Budget',data(){return{list:[],idSort:'asc',show:false,mode:'add',current:{},increase:true,categories:['差旅费','交通费','培训费','设备维护费','办公费'],form:{year:new Date().getFullYear(),category:'',amount:''}}},computed:{isAdmin(){return(currentUser()||{}).role==='ADMIN'},sortedList(){return[...this.list].sort((a,b)=>this.idSort==='asc'?a.id-b.id:b.id-a.id)}},created(){this.getList()},methods:{sort(){this.idSort=this.idSort==='asc'?'desc':'asc'},async getList(){try{const r=await api('/budget');if(r.code===200)this.list=r.data||[];else alert(r.message)}catch(e){alert('无法连接服务器')}},openAdd(){this.mode='add';this.form={year:new Date().getFullYear(),category:'',amount:''};this.show=true},openAdjust(x){this.mode='adjust';this.current=x;this.form.amount='';this.increase=true;this.show=true},async submit(){if(!this.form.amount||this.form.amount<=0)return alert('请输入大于 0 的金额');let r;if(this.mode==='add'){if(!this.form.category)return alert('请选择预算类别');r=await api('/budget',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({year:this.form.year,category:this.form.category,budgetAmount:this.form.amount,usedAmount:0})})}else r=await api(`/budget/${this.current.id}/adjust?amount=${this.form.amount}&increase=${this.increase}`,{method:'POST'});if(r.code===200){alert(r.message);this.show=false;this.getList()}else alert(r.message||'操作失败')},money(x){return Number(x||0).toFixed(2)},left(x){return Number(x.budgetAmount||0)-Number(x.usedAmount||0)},rate(x){return x.budgetAmount?(Number(x.usedAmount||0)/Number(x.budgetAmount)*100).toFixed(2):'0.00'},level(x){const r=+this.rate(x);return r<70?'normal':r<90?'notice':r<100?'warning':'over'},text(x){const r=+this.rate(x);return r<70?'正常':r<90?'提醒':r<100?'警告':'已超预算'}}}
</script>
<style scoped>.page{width:100%}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.page-header h2{margin:0 0 8px;color:#172033}.page-header p{margin:0;color:#718096;font-size:13px}.primary{border:0;border-radius:8px;padding:10px 17px;background:linear-gradient(135deg,#2563eb,#397bc1);color:#fff;font-weight:600;cursor:pointer;box-shadow:0 5px 12px #2563eb33}.table-box{background:#fff;border-radius:12px;padding:20px;box-shadow:0 3px 14px #0f172a0d;overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:14px 12px;border-bottom:1px solid #edf1f6;text-align:center;white-space:nowrap}th{background:#f7f9fc;color:#526277;font-size:12px}th button{border:0;background:transparent;color:inherit;cursor:pointer}td{color:#405066;font-size:13px}.tag{padding:5px 10px;border-radius:14px;background:#edf4ff;color:#2563eb}.status{padding:5px 10px;border-radius:14px;font-size:12px}.normal{background:#ecfdf3;color:#15803d}.notice{background:#fff7ed;color:#c2410c}.warning{background:#fff1f2;color:#e11d48}.over{background:#fee2e2;color:#b91c1c}.adjust{border:1px solid #bfdbfe;border-radius:7px;background:#eff6ff;color:#2563eb;padding:6px 10px;cursor:pointer}.empty{padding:42px;color:#94a3b8}.mask{position:fixed;inset:0;z-index:3000;display:flex;align-items:center;justify-content:center;background:#0f172a73;backdrop-filter:blur(3px)}.modal{width:440px;padding:25px;background:#fff;border-radius:16px;box-shadow:0 24px 60px #0f172a4d}.head{display:flex;justify-content:space-between;margin-bottom:22px}.head h3{margin:0 0 6px;color:#172033}.head p{margin:0;color:#8491a5;font-size:13px}.head button{border:0;background:transparent;font-size:26px;color:#94a3b8;cursor:pointer}.modal label{display:block;margin:16px 0 8px;color:#405066;font-size:13px;font-weight:600}.modal input,.select select{width:100%;height:43px;border:1px solid #dbe3ef;border-radius:8px;padding:0 12px;outline:0;font-size:14px}.modal input:focus,.select select:focus{border-color:#397bc1;box-shadow:0 0 0 3px #397bc11f}.select{position:relative}.select:after{content:'⌄';position:absolute;right:14px;top:8px;color:#397bc1;font-size:20px;pointer-events:none}.select select{appearance:none;background:#fff;cursor:pointer}.money{display:flex;align-items:center;border:1px solid #dbe3ef;border-radius:8px;overflow:hidden}.money:focus-within{border-color:#397bc1;box-shadow:0 0 0 3px #397bc11f}.money span{padding:0 12px;color:#397bc1;font-weight:bold}.money input{border:0;box-shadow:none!important}.info{padding:14px;background:#f4f8ff;border-radius:10px;color:#64748b;font-size:12px}.info strong{color:#2563eb;font-size:19px}.switch{display:grid;grid-template-columns:1fr 1fr;margin:20px 0 4px;padding:4px;background:#f1f5f9;border-radius:9px}.switch button{border:0;border-radius:7px;padding:10px;background:transparent;color:#64748b;cursor:pointer}.switch .active{background:#fff;color:#2563eb;box-shadow:0 2px 6px #0f172a14;font-weight:600}.hint{color:#94a3b8;font-size:12px}.foot{display:flex;justify-content:flex-end;gap:10px;margin-top:25px}.cancel{border:0;border-radius:8px;padding:10px 18px;background:#eef2f7;color:#526277;cursor:pointer}</style>
